WITH exploded AS (SELECT id, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS tier_value) SELECT id, currency, tier_value, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC) AS tier_value_dense_rank, MAX(tier_value) OVER (PARTITION BY currency) AS currency_max_tier_value FROM exploded;
